<?php use Hls\Http\View as V;
$branchAllowed=fn(int $b)=>in_array($b,$model['activeBranches'],true)&&$access->branch($b);
$start=function(string $action,string $label,string $path='/trucking/manifests',array $hidden=[])use($row){echo '<form class="panel master-form" method="post" aria-label="'.V::escape($label).'" action="'.V::escape($this->url($path)).'" data-confirm="Catat tindakan aktual ini? Histori akan disimpan."><h2>'.V::escape($label).'</h2>'.$this->csrf();foreach(['id'=>$row['id'],'version'=>$row['version'],'action'=>$action,'request_key'=>bin2hex(random_bytes(32))]+$hidden as $f=>$v)echo '<input type="hidden" name="'.V::escape($f).'" value="'.V::escape($v).'">';};
$end=function(string $label){echo '<button class="primary" type="submit">'.V::escape($label).'</button></form>';};
$text=function(string $name,string $label,string $id,bool $required=true){echo $this->component('field',['name'=>$name,'label'=>$label,'type'=>'text','id'=>$id,'required'=>$required]);};
?>
<?php if($kind==='dn'): ?>
<?php if($row['status']==='created'&&$access->can('expedition.confirm')&&$branchAllowed((int)$row['origin_branch_id'])):$start('confirm_dn','Konfirmasi DN','/trucking/dns'); ?><p>Nomor resmi diterbitkan saat konfirmasi. Data penting DN kemudian dibekukan.</p><?php $end('Konfirmasi DN');endif ?>
<?php if($access->can('expedition.receive')&&$branchAllowed((int)$row['destination_branch_id'])&&!$membership&&in_array($row['status'],['arrived','received'],true)):
$finish=$row['status']==='received';$start($finish?'finish':'receive',$finish?'Selesaikan DN':'Konfirmasi Penerimaan','/trucking/receipts');
if(!$finish):$text('recipient_name','Nama penerima aktual','receipt-recipient');$text('condition_note','Catatan kondisi penerimaan','receipt-condition'); ?><label class="check"><input type="checkbox" name="whole_confirm" value="1" required>Jumlah dan kondisi sesuai; diterima utuh</label><p>Jika ada selisih, jangan konfirmasi penerimaan. Buat klaim operasional.</p><?php endif;$end($finish?'Selesaikan DN':'Terima Barang');endif ?>
<?php if($access->can('expedition.claim.report')): ?><p><a class="button" href="<?= V::escape($this->url('/trucking/claims?mode=create&dn_id='.$row['id'])) ?>">Laporkan Klaim</a></p><?php endif ?>
<?php else:$legs=$model['legs'];$stop=$model['stop']; ?>
<section class="panel"><h2>Lintasan Perjalanan</h2><ol><?php foreach($legs as $leg):$s=json_decode($leg['snapshot'],true,512,JSON_THROW_ON_ERROR); ?><li><?= V::escape(($s['origin']??'').' → '.($s['destination']??'').' · '.($s['route']??'')) ?><?= $leg['arrived_at']?' · Tiba kendaraan '.V::escape($leg['arrived_at']).' WITA':'' ?></li><?php endforeach ?></ol><p>Posisi kendaraan: stop <?= (int)$row['current_stop'] ?> dari <?= count($legs) ?>. Kedatangan DN dicatat terpisah.</p></section>
<?php if($row['status']==='draft'&&$canOrigin&&$model['nextRoutes']):$start('append_leg','Tambah Leg Perjalanan');echo $this->component('field',['name'=>'route_id','label'=>'Leg lanjutan','type'=>'select','required'=>true,'options'=>array_map(fn($r)=>['id'=>$r['id'],'name'=>$r['code'].' — '.$r['name']],$model['nextRoutes'])]); ?><p>Lokasi awal harus sama dengan lokasi akhir leg sebelumnya. Lokasi berulang dalam satu trip belum didukung.</p><?php $end('Tambah Leg');endif ?>
<?php if($row['status']==='draft'&&$canOrigin):$start('confirm','Konfirmasi Manifest'); ?><p>Semua DN harus terkonfirmasi dan tujuan berada pada lintasan. Kendaraan wajib ditetapkan.</p><?php $end('Konfirmasi Manifest');endif ?>
<?php if($row['status']==='draft'&&$canOrigin):$start('assign_vehicle','Penetapan Armada Draf');foreach(['vehicle_id'=>'Kendaraan','driver_id'=>'Driver'] as $name=>$label)echo $this->component('field',['name'=>$name,'id'=>'assign-'.$name,'label'=>$label.' draf','type'=>'select','value'=>$row[$name]??'','required'=>$name==='vehicle_id','options'=>[['id'=>'','name'=>'Belum ditetapkan'],...array_map(fn($r)=>['id'=>$r['id'],'name'=>$r['code'].' — '.$r['name']],$model['assignments'][$name]??[])]]);$end('Simpan Armada Draf');endif ?>
<?php if($access->can('expedition.transit')):
if(in_array($row['status'],['confirmed','transit'],true)&&$branchAllowed($stop['branch'])&&(int)$row['current_stop']<count($legs)):$start('depart','Keberangkatan Aktual');$end('Berangkatkan Kendaraan');endif;
if($row['status']==='departed'&&isset($legs[(int)$row['current_stop']])&&$branchAllowed((int)$legs[(int)$row['current_stop']]['destination_branch_id'])):$start('arrive','Kedatangan Kendaraan'); ?><p>Tindakan ini hanya mencatat kendaraan tiba, belum mencatat kedatangan DN atau penerimaan pelanggan.</p><?php $end('Catat Kendaraan Tiba');endif;
if($row['status']==='transit'&&$branchAllowed($stop['branch'])):
$pending=array_values(array_filter($members,fn($i)=>!$i['removed_at']&&$i['dn_status']==='departed'));
if($pending):$start('record_arrival','Kedatangan DN Aktual');foreach($pending as $item): ?><label class="check"><input type="checkbox" name="dn_ids[]" value="<?= (int)$item['dn_id'] ?>"><?= V::escape(($item['official_number']??$item['number']).' — '.$item['description']) ?></label><?php endforeach;$end('Catat DN Tiba');endif;
foreach($members as $item)if(!$item['removed_at']&&in_array($item['dn_status'],['transit','arrived'],true)&&(int)$item['current_location_id']===$stop['location']):$start('unload','Turunkan DN '.$item['number'],'/trucking/manifests',['dn_id'=>$item['dn_id']]);$text('note','Alasan/catatan penurunan','unload-note-'.$item['id']);$end('Catat Penurunan DN');endif;
if((int)$row['current_stop']===count($legs)):$start('complete','Selesaikan Perjalanan'); ?><p>Hanya menutup perjalanan kendaraan setelah seluruh DN diturunkan/dipindah; tidak membuat penerimaan otomatis.</p><?php $end('Selesaikan Manifest');endif;endif;endif ?>
<?php if($access->can('expedition.manifest')&&$branchAllowed($stop['branch'])&&in_array($row['status'],['draft','confirmed','transit'],true)&&$model['targets']):
foreach($members as $item)if(!$item['removed_at']&&in_array($item['dn_status'],['created','confirmed','transit'],true)&&(int)$item['current_location_id']===$stop['location']): ?>
<?php $start('move','Pindahkan '.$item['number'],'/trucking/manifests',['dn_id'=>$item['dn_id']]);echo $this->component('field',['name'=>'target_choice','label'=>'Manifest tujuan','id'=>'move-target-'.$item['id'],'type'=>'select','required'=>true,'options'=>array_map(fn($target)=>['id'=>$target['id'].':'.$target['version'],'name'=>$target['number']],$model['targets'])]);$text('note','Alasan pergantian manifest','move-note-'.$item['id']);$end('Pindahkan DN');endif;endif ?>
<?php if($canOrigin&&in_array($row['status'],['draft','confirmed'],true)):$start('cancel','Batalkan Manifest Sebelum Berangkat');$text('note','Alasan pembatalan','cancel-note'); ?><p>Pindahkan seluruh DN terlebih dahulu. Nomor resmi tetap tersimpan dan tidak digunakan ulang.</p><?php $end('Batalkan Manifest');endif ?>
<?php endif ?>
